#!/bin/bash
# scratch: dry run (no --go) of the stage-B start through trainsuite: prints the command and writes the preview of the composed config
cd /mnt/c/Auto-research/autoresearch || exit 1
export AR_PROJECT=../bev_fusion
HYP="t22 (card experiments/t22_student_encoder): the distilled EfficientViT-B1 student (stage A2), trained in the t21 P4 chain (warm start t20.base_s0, 1500 steps, lr 1e-4, student 1e-5, distillation anchor 0.5 falling to 0.05 at half the steps) replaces the frozen DualBEV + BEVFusion encoders and the res4 depth of the CURRENT frame and keeps every guard of the t21 P4 control inside its margin at a fraction of the image-side time"
PRED="VAL 1000 frames, dt 0, against t21.pair4_s0 (lane divider IoU@1 0.5495, drivable IoU@0 0.7918, mAP fusion area 0.4154, vehicle AP@2 40-60 m 0.5491 fusion area / 0.3740 plain): every guard within -m of the control (m = max(0.010, half-width of the paired scene bootstrap)); velocity EPE at moving centres within +0.05 m/s; vehicle AP@2 40-60 m within -0.03; image side at most 0.5 of the teachers' time (idle GPU, batch 1: measured 0.37 fp32, 0.54 fp16); a lane gain from the BEV-loss fine-tune is possible but not predicted"
RULE="by hand: composed from the card (section 1, decision rule), one seed: STAND-IN candidate when every guard is not below the control by more than m (point estimate and the lower end of the interval not beyond 2 m) and the cost row holds -> seed twin of student and control before any adoption (one seed never gives KEEP); BETTER when a map or line guard exceeds +m with the interval excluding 0; CUT when a guard is below the control by more than 2 m with the interval entirely below -m; INCONCLUSIVE when an interval straddles a margin -> a second seed"
python3 -m trainsuite start ../bev_fusion/training/configs/t22_B_s0.json --id t22.B_s0 --hyp "$HYP" --pred "$PRED" --rule "$RULE" 2>&1 | cut -c1-400
